. "$PSScriptRoot\Common-Utilities.ps1"
function New-ToolkitHtmlReport {
 [CmdletBinding()]param([Parameter(Mandatory)]$Data,[string]$Title='Rapihkan Win11 report')
 Initialize-ToolkitFolders;$json=$Data|ConvertTo-Json -Depth 8;$safe=[System.Net.WebUtility]::HtmlEncode($json);$summary=if($Data -is [array]){"$($Data.Count) result item(s)"}else{'One result set'};$stamp=Get-Date -Format 'yyyy-MM-dd HH:mm:ss';$p=Join-Path (Join-Path (Get-ToolkitPaths).Reports 'Audit') "Report-$(Get-NowStamp).html"
 @"
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>$Title</title><style>:root{color-scheme:dark}body{margin:0;background:#071d33;color:#e8f5fb;font:16px Segoe UI,Arial,sans-serif}.wrap{max-width:1100px;margin:auto;padding:32px}.hero{background:linear-gradient(120deg,#0a3658,#09506e);border:1px solid #2b83a9;border-radius:18px;padding:28px}.eyebrow{color:#72e1bd;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin:20px 0}.card{background:#0b2a45;border:1px solid #205575;border-radius:12px;padding:18px}.card small{color:#a8c9db}.card strong{font-size:22px;display:block;margin-top:6px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#041523;border:1px solid #205575;border-radius:12px;padding:20px;color:#cce9f6}</style><body><main class="wrap"><section class="hero"><div class="eyebrow">Rapihkan Win11</div><h1>$Title</h1><p>Generated locally on $stamp. This report does not upload data.</p></section><section class="grid"><article class="card"><small>Report summary</small><strong>$summary</strong></article><article class="card"><small>Safety model</small><strong>Review first</strong></article><article class="card"><small>Data location</small><strong>Local only</strong></article></section><h2>Raw results</h2><pre>$safe</pre></main></body></html>
"@|Set-Content -LiteralPath $p -Encoding utf8
 $p
}